def hook(ctx, nb):
    action = ctx.get("action", {})
    state = ctx.get("state", {})
    if action.get("tool") == "execute_sql":
        sql = action.get("query", "")
        result = state.get("last_result", "")
        error = state.get("last_error_kind", "")
        if not error and isinstance(result, list) and len(result) == 0:
            sql_upper = sql.strip().upper()
            if sql_upper.startswith("INSERT") or sql_upper.startswith("UPDATE") or sql_upper.startswith("DELETE"):
                nb["mutation_executed"] = True
                nb["mutation_type"] = sql_upper.split()[0]
                nb["mutation_verified"] = False
        if sql_upper.startswith("SELECT") and nb.get("mutation_executed") and not nb.get("mutation_verified"):
            nb["mutation_verified"] = True
    return None

def hook(ctx, nb):
    if nb.get("mutation_executed") and not nb.get("mutation_verified") and not nb.get("committed"):
        return {"message": "You have executed a mutation but not yet verified it. Please run a SELECT query to verify the affected rows, then commit the actual data values."}
    state = ctx.get("state", {})
    error_kind = state.get("last_error_kind", "")
    if error_kind in ("syntax", "unknown_col") and not nb.get("hinted_backticks"):
        nb["hinted_backticks"] = True
        return {"message": "Your SQL encountered an error. If your table or column names contain spaces or special characters, remember to wrap them in backticks, e.g., `table name`."}
    return None

def is_success_message(text):
    if not isinstance(text, str):
        return False
    if any(ch.isdigit() for ch in text):
        return False
    pattern = r'(successfully|inserted|updated|deleted|record|row added|update completed|record inserted|commit)'
    return re.search(pattern, text, re.IGNORECASE) is not None

def hook(ctx, nb):
    action = ctx.get("action", {})
    if action.get("tool") == "commit_final_answer":
        predicates = ctx.get("predicates", {})
        if predicates.get("mutation_task"):
            answers = action.get("answers", [])
            if answers and all(isinstance(a, str) and is_success_message(a) for a in answers):
                if not nb.get("blocked_commit_count"):
                    nb["blocked_commit_count"] = 1
                else:
                    nb["blocked_commit_count"] += 1
                if nb["blocked_commit_count"] <= 2:
                    return {"kind": "block_and_prompt", "message": "Your answer appears to be a generic success message. For mutation tasks, you must provide the actual data values (e.g., the inserted row, the updated row, or the deleted row). Please verify the mutation with a SELECT and then commit the relevant data values."}
    return None
